// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = c.owner();
    }

    function testFuzz_property(uint256 ethAmount) public {
        ethAmount = bound(ethAmount, 0, 1e21);

        // Owner initializes the distribution, receiving totalDistributed tokens.
        vm.prank(owner);
        c.NETM();

        // Owner (not yet blacklisted, distribution still open) claims tokens.
        // The grant must ADD to his existing balance, preserving it.
        vm.deal(owner, ethAmount);
        vm.prank(owner);
        try c.getTokens{value: ethAmount}() {
            // general rule: distribution preserves the recipient's prior balance:
            // balanceOf(owner) == totalDistributed + granted value
            assertTrue(
                c.balanceOf(owner) == 250000000e18 + c.value() || c.value() != 2500e18,
                "distribution must add to, not overwrite, prior balance"
            );
        } catch {
            // if the claim reverted, the balance must still be the NETM grant
            assertTrue(c.balanceOf(owner) == 250000000e18, "revert must leave balance intact");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 burnAmount) public {
        // keep burnAmount in the admissible domain: burnable but not the whole allocation
        bound(burnAmount, 1, c.totalDistributed() - 1);

        // owner (deployer = this) initializes balances via NETM
        c.NETM();

        // owner shrinks his own balance by a fuzzed amount, so a prior nonzero balance exists
        c.burn(burnAmount);
        uint256 priorBalance = c.balanceOf(address(this));

        // owner (not blacklisted) claims the current grant through getTokens/distr
        uint256 grant = c.value();
        c.getTokens();

        // GENERAL RULE: distribution INCREASES the recipient's balance by the granted amount
        // (mutant overwrites: balance becomes only `grant`)
        assertTrue(c.balanceOf(address(this)) == priorBalance + grant);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // initialize owner balances via NETM (deployer == owner == this contract)
        c.NETM();

        // admissible domain: a fresh non-owner recipient
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(!c.blacklist(actor));

        // give recipient a nonzero prior balance by transferring from the owner
        amount = bound(amount, 1, c.balanceOf(address(this)));
        vm.prank(address(this));
        c.transfer(actor, amount);

        // claim amount is the current drip value (read before the claim mutates it)
        uint256 grant = c.value();
        vm.assume(grant > 0);

        // recipient claims tokens through getTokens (admissible, not yet blacklisted)
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.getTokens();

        // RULE: a distribution adds the granted amount to the recipient's existing balance
        assertTrue(c.balanceOf(actor) == amount + grant);
    }
}
